<?php
declare(strict_types=1);
require_once __DIR__.'/business_documents.php';require_once __DIR__.'/operations.php';
function financeRecurringAdvance(string $date,string $frequency,int $anchor):string {
 if($frequency!=='yearly')return zgsAdvanceDate($date,$frequency,$anchor);
 if(!zgsValidDate($date)||$anchor<1||$anchor>31)throw new InvalidArgumentException('Wiederholung ungültig.');$d=new DateTimeImmutable($date,new DateTimeZone('Europe/Berlin'));$next=$d->modify('first day of this month')->modify('+1 year');return $next->setDate((int)$next->format('Y'),(int)$next->format('m'),min($anchor,(int)$next->format('t')))->format('Y-m-d');
}
function financeRecurringSave(PDO $pdo,int $admin,array $in,int $id=0):int {
 $kind=(string)($in['kind']??'');$title=opsText($in,'title',190,true);$freq=(string)($in['frequency']??'');$due=(string)($in['next_due_date']??'');$days=filter_var($in['due_days']??14,FILTER_VALIDATE_INT);$anchor=filter_var($in['anchor_day']??(int)substr($due,8,2),FILTER_VALIDATE_INT);$source=filter_var($in['source_invoice_id']??0,FILTER_VALIDATE_INT);$property=filter_var($in['property_id']??0,FILTER_VALIDATE_INT);$notes=opsText($in,'notes',5000);
 if(!in_array($kind,['invoice','expense_review'],true)||!in_array($freq,['weekly','biweekly','monthly','quarterly','yearly'],true)||!zgsValidDate($due)||$days===false||$days<0||$days>365||$anchor===false||$anchor<1||$anchor>31||$source===false||$source<0||$property===false||$property<0)throw new InvalidArgumentException('Vorlage: Art, Intervall, Datum oder Zuordnung ungültig.');
 $expected=trim((string)($in['expected_amount']??''));$cents=$expected===''?null:financeCents($expected,'de');if($cents!==null&&$cents<1)throw new InvalidArgumentException('Erwarteter Betrag positiv oder leer.');if($kind==='expense_review'&&$source)throw new InvalidArgumentException('Ausgabenprüfung verwendet kein Rechnungsoriginal.');$data=['kind'=>$kind,'title'=>$title,'source_invoice_id'=>$source?:null,'property_id'=>$property?:null,'frequency'=>$freq,'next_due_date'=>$due,'anchor_day'=>$anchor,'due_days'=>$days,'expected_cents'=>$cents,'notes'=>$notes,'active'=>empty($in['active'])?0:1];
 $pdo->beginTransaction();try{$old=[];if($id){$q=$pdo->prepare('SELECT * FROM finance_recurrences WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetch();if(!$old)throw new RuntimeException('Vorlage fehlt.');if(opsVersion($in)!==(int)$old['row_version'])throw new RuntimeException('Vorlage inzwischen geändert. Neu laden.');if($old['kind']!==$kind||(int)$old['source_invoice_id']!==$source)throw new RuntimeException('Art und Original einer bestehenden Vorlage unveränderlich; gegebenenfalls pausieren und neue Vorlage anlegen.');}
 if($kind==='invoice'){if(!$source)throw new RuntimeException('Ausgestellte Originalrechnung wählen.');$q=$pdo->prepare("SELECT id,status,document_kind FROM invoices WHERE id=? FOR UPDATE");$q->execute([$source]);$base=$q->fetch();if(!$base||$base['document_kind']!=='invoice'||($data['active']&&!in_array($base['status'],['issued','paid'],true))||!invItems($pdo,$source))throw new RuntimeException('Ausgestellte, nicht stornierte Rechnung mit Positionen erforderlich.');}if($property)opsLock($pdo,'properties',$property);
 if($id)$pdo->prepare('UPDATE finance_recurrences SET kind=?,title=?,source_invoice_id=?,property_id=?,frequency=?,next_due_date=?,anchor_day=?,due_days=?,expected_cents=?,notes=?,active=?,row_version=row_version+1 WHERE id=?')->execute([...array_values($data),$id]);else{$pdo->prepare('INSERT INTO finance_recurrences(kind,title,source_invoice_id,property_id,frequency,next_due_date,anchor_day,due_days,expected_cents,notes,active) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute(array_values($data));$id=(int)$pdo->lastInsertId();}$pdo->prepare('INSERT INTO finance_recurrence_revisions(recurrence_id,admin_id,old_json,new_json) VALUES(?,?,?,?)')->execute([$id,$admin,json_encode($old,JSON_THROW_ON_ERROR),json_encode($data,JSON_THROW_ON_ERROR)]);gszAudit($pdo,$admin,'finance_recurrence_saved',['recurrence_id'=>$id]);$pdo->commit();return $id;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeRecurringState(PDO $pdo,int $id,bool $lock=false):array {
 $q=$pdo->prepare('SELECT * FROM finance_recurrences WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$schedule=$q->fetch();if(!$schedule)throw new RuntimeException('Vorlage fehlt.');$invoice=null;$items=[];
 if($schedule['kind']==='invoice'){$q=$pdo->prepare('SELECT * FROM invoices WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$schedule['source_invoice_id']]);$invoice=$q->fetch();if(!$invoice||$invoice['document_kind']!=='invoice'||!in_array($invoice['status'],['issued','paid'],true))throw new RuntimeException('Originalrechnung fehlt/storniert. Vorlage prüfen.');$q=$pdo->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY position,id LIMIT 501'.($lock?' FOR UPDATE':''));$q->execute([$invoice['id']]);$items=$q->fetchAll();if(!$items||count($items)>500)throw new RuntimeException('Originalpositionen fehlen/Limit500 überschritten.');}
 $q=$pdo->prepare('SELECT * FROM finance_recurrence_occurrences WHERE recurrence_id=? ORDER BY scheduled_for LIMIT 1001'.($lock?' FOR UPDATE':''));$q->execute([$id]);$occurrences=$q->fetchAll();if(count($occurrences)>1000)throw new RuntimeException('Historienlimit1000; gezielte Archiv-/Ladestrategie erforderlich.');return ['schedule'=>$schedule,'invoice'=>$invoice,'items'=>$items,'occurrences'=>$occurrences];
}
function financeRecurringPlan(array $state,string $through):array {
 $s=$state['schedule'];if(!$s['active'])throw new RuntimeException('Vorlage pausiert.');$max=(new DateTimeImmutable('today',new DateTimeZone('Europe/Berlin')))->modify('+1 year')->format('Y-m-d');if(!zgsValidDate($through)||$through>$max||$through<$s['next_due_date'])throw new RuntimeException('Horizont ab nächster Fälligkeit bis maximal ein Jahr.');$known=array_fill_keys(array_column($state['occurrences'],'scheduled_for'),true);$date=$s['next_due_date'];$rows=[];$steps=0;
 while($date<=$through){if(++$steps>24)throw new RuntimeException('Maximal24 Fälligkeiten je Vorschau. Zeitraum verkleinern oder Rückstand prüfen.');$rows[]=['scheduled_for'=>$date,'existing'=>isset($known[$date])];$date=financeRecurringAdvance($date,$s['frequency'],(int)$s['anchor_day']);}return ['through'=>$through,'rows'=>$rows,'next_due_date'=>$date];
}
function financeRecurringPreview(PDO $pdo,int $admin,int $id,string $through):string {
 $pdo->beginTransaction();try{$state=financeRecurringState($pdo,$id,true);$plan=financeRecurringPlan($state,$through);$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO finance_recurrence_proposals(token,admin_id,recurrence_id,fingerprint,payload) VALUES(?,?,?,?,?)')->execute([$token,$admin,$id,hash('sha256',json_encode($state,JSON_THROW_ON_ERROR)),json_encode($plan,JSON_THROW_ON_ERROR)]);$pdo->commit();return $token;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeRecurringApply(PDO $pdo,int $admin,string $token):array {
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM finance_recurrence_proposals WHERE token=? AND admin_id=? FOR UPDATE');$q->execute([$token,$admin]);$p=$q->fetch();if(!$p)throw new RuntimeException('Vorschau fehlt.');$plan=json_decode($p['payload'],true,32,JSON_THROW_ON_ERROR);if($p['applied_at']){$pdo->commit();return $plan['created']??[];}if(strtotime($p['created_at'].' UTC')<time()-7200)throw new RuntimeException('Vorschau abgelaufen.');$state=financeRecurringState($pdo,(int)$p['recurrence_id'],true);if(!hash_equals($p['fingerprint'],hash('sha256',json_encode($state,JSON_THROW_ON_ERROR))))throw new RuntimeException('Vorlage/Original/Herkunft geändert. Neu berechnen.');if(financeRecurringPlan($state,$plan['through'])!==$plan)throw new RuntimeException('Vorschau unplausibel.');$s=$state['schedule'];$created=[];
 foreach($plan['rows'] as $row){if($row['existing'])continue;$day=$row['scheduled_for'];$invoice=null;$task=null;if($s['kind']==='invoice'){$old=$state['invoice'];$invoice=businessCopy($pdo,$old,'invoice',null,'draft',null,null,1,'Wiederkehrender Entwurf aus '.$old['number'].' zum '.$day);$pdo->prepare('UPDATE invoices SET service_date=?,due_date=?,property_id=? WHERE id=?')->execute([$day,planDate($day,(int)$s['due_days']),$s['property_id']?:$old['property_id'],$invoice]);invEvent($pdo,$invoice,'recurring_draft','Vorlage #'.$s['id'].' / '.$day);}
 else{$note='Finanz-Prüfaufgabe, keine Buchung und kein Beleg. Originalbeleg prüfen/hochladen.'.($s['expected_cents']!==null?' Erwartung (kein Istwert): '.financeDecimal((int)$s['expected_cents']).' EUR.':'').' '.$s['notes'];$pdo->prepare("INSERT INTO tasks(property_id,title,due_date,notes,plan_locked) VALUES(?,?,?,?,1)")->execute([$s['property_id'],mb_substr('Ausgabe prüfen: '.$s['title'],0,190),$day,$note]);$task=(int)$pdo->lastInsertId();opsEvent($pdo,$admin,'task',$task,'created',[],['source'=>'finance_recurrence','recurrence_id'=>$s['id'],'scheduled_for'=>$day]);}
 $pdo->prepare('INSERT INTO finance_recurrence_occurrences(recurrence_id,scheduled_for,invoice_id,task_id) VALUES(?,?,?,?)')->execute([$s['id'],$day,$invoice,$task]);$created[]=['day'=>$day,'invoice_id'=>$invoice,'task_id'=>$task];}
 $pdo->prepare('UPDATE finance_recurrences SET next_due_date=?,row_version=row_version+1 WHERE id=?')->execute([$plan['next_due_date'],$s['id']]);$plan['created']=$created;$pdo->prepare('UPDATE finance_recurrence_proposals SET applied_at=UTC_TIMESTAMP(),payload=? WHERE token=?')->execute([json_encode($plan,JSON_THROW_ON_ERROR),$token]);gszAudit($pdo,$admin,'finance_recurrence_applied',['recurrence_id'=>$s['id'],'created'=>count($created)]);$pdo->commit();return $created;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
